# STATUS (2026-10-14): REFERENCE ONLY. The site is a static build.py site on Vercel, not WordPress.
# FAQ content and FAQPage schema are generated by FAQ_CATEGORIES in build.py; edit there.
"""
build_schema.py
Generates JSON-LD structured data (schema.org) for First Rehabilitation of North Palm Beach,
reusing the Q&A knowledge base in first_rehab_qa_training.py so the FAQ schema always
matches the training answers.

Outputs:
  first_rehab_schema.html       -> paste-ready <script type="application/ld+json"> block
  first_rehab_schema.json       -> raw JSON-LD (validate at validator.schema.org)
  first_rehab_wordpress.php     -> functions.php snippet that injects the schema sitewide
                                   (LocalBusiness graph) and FAQPage only on the FAQ page
"""
import json
import first_rehab_qa_training as q

SITE = "https://REPLACE-WITH-YOUR-DOMAIN.com"      # TODO
PHONE = "+1-561-000-0000"                          # TODO
LOGO = f"{SITE}/wp-content/uploads/logo.png"       # TODO
IMAGE = f"{SITE}/wp-content/uploads/clinic.jpg"    # TODO
FAQ_URL = f"{SITE}/faq/"                           # TODO

ORG_ID = f"{SITE}/#clinic"
SITE_ID = f"{SITE}/#website"


def faq_schema():
    return {
        "@type": "FAQPage",
        "@id": f"{FAQ_URL}#faq",
        "url": FAQ_URL,
        "isPartOf": {"@id": SITE_ID},
        "about": {"@id": ORG_ID},
        "mainEntity": [
            {
                "@type": "Question",
                "name": it.question,
                "acceptedAnswer": {"@type": "Answer", "text": it.answer},
            }
            for it in q.QA_ITEMS
        ],
    }


def business_graph():
    services = [
        ("Physical Therapy", "Orthopedic, post-surgical, balance, neuro, and pain rehabilitation."),
        ("Occupational Therapy", "Therapy focused on daily function, work, and independence."),
        ("Certified Hand Therapy", "Treatment for hand, wrist, and upper-extremity injuries, including custom splinting."),
        ("Wellness and Gym Program (F.I.T. by First)", "Supervised strength and fitness program for patients after therapy."),
    ]
    return [
        {
            "@type": ["MedicalClinic", "Physiotherapy"],
            "@id": ORG_ID,
            "name": q.BUSINESS_NAME,
            "alternateName": q.SHORT_NAME,
            "url": SITE,
            "logo": LOGO,
            "image": IMAGE,
            "telephone": PHONE,
            "foundingDate": str(q.YEAR_FOUNDED),
            "founder": {"@type": "Person", "name": q.FOUNDER},
            "employee": [{
                "@type": "Person",
                "name": q.HAND_THERAPIST,
                "jobTitle": "Certified Hand Therapist",
            }],
            "address": {
                "@type": "PostalAddress",
                "streetAddress": "733 US Highway 1, Suite 2A",
                "addressLocality": "North Palm Beach",
                "addressRegion": "FL",
                "postalCode": "33408",
                "addressCountry": "US",
            },
            "areaServed": [
                {"@type": "City", "name": "North Palm Beach"},
                {"@type": "City", "name": "Palm Beach Gardens"},
                {"@type": "City", "name": "Juno Beach"},
                {"@type": "City", "name": "Jupiter"},
            ],
            "medicalSpecialty": ["PhysicalTherapy", "Rehabilitation"],
            "openingHoursSpecification": [{
                "@type": "OpeningHoursSpecification",
                "dayOfWeek": ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday"],
                "opens": "08:00",      # TODO confirm
                "closes": "17:00",     # TODO confirm
            }],
            "hasOfferCatalog": {
                "@type": "OfferCatalog",
                "name": "Services",
                "itemListElement": [
                    {"@type": "Offer", "itemOffered": {
                        "@type": "MedicalTherapy" if i < 3 else "Service",
                        "name": n, "description": d}}
                    for i, (n, d) in enumerate(services)
                ],
            },
            "sameAs": [
                "https://www.facebook.com/REPLACE",     # TODO
                "https://www.instagram.com/REPLACE",    # TODO
                "https://www.youtube.com/@REPLACE",     # TODO
            ],
        },
        {
            "@type": "WebSite",
            "@id": SITE_ID,
            "url": SITE,
            "name": q.BUSINESS_NAME,
            "publisher": {"@id": ORG_ID},
            "inLanguage": "en-US",
        },
        {
            "@type": "PodcastSeries",
            "@id": f"{SITE}/podcast/#series",
            "name": q.PODCAST_NAME,
            "url": f"{SITE}/podcast/",                 # TODO
            "publisher": {"@id": ORG_ID},
            "description": "Conversations about pain, recovery, and performance from First Rehabilitation.",
        },
    ]


def wrap(graph):
    return {"@context": "https://schema.org", "@graph": graph}


def script_tag(obj):
    return ('<script type="application/ld+json">\n'
            + json.dumps(obj, indent=2, ensure_ascii=False)
            + "\n</script>")


if __name__ == "__main__":
    combined = wrap(business_graph() + [faq_schema()])

    with open("first_rehab_schema.json", "w", encoding="utf-8") as f:
        json.dump(combined, f, indent=2, ensure_ascii=False)

    html = ("<!-- Sitewide: LocalBusiness + WebSite + PodcastSeries -->\n"
            + script_tag(wrap(business_graph()))
            + "\n\n<!-- FAQ page only -->\n"
            + script_tag(wrap([faq_schema()])) + "\n")
    with open("first_rehab_schema.html", "w", encoding="utf-8") as f:
        f.write(html)

    def php_json(obj):
        # Safe for embedding in PHP nowdoc
        return json.dumps(obj, indent=2, ensure_ascii=False)

    php = f"""<?php
/**
 * First Rehabilitation: structured data (JSON-LD)
 * Add to your child theme's functions.php, or save as a small plugin.
 * If Yoast / Rank Math / AIOSEO is installed, disable ITS LocalBusiness and FAQ
 * schema first, or you will output duplicate/conflicting markup.
 */
add_action('wp_head', function () {{
    // Sitewide business graph
    $business = <<<'JSON'
{php_json(wrap(business_graph()))}
JSON;
    echo '<script type="application/ld+json">' . $business . '</script>' . "\\n";

    // FAQPage only on the FAQ page (change slug to match)
    if (is_page('faq')) {{
        $faq = <<<'JSON'
{php_json(wrap([faq_schema()]))}
JSON;
        echo '<script type="application/ld+json">' . $faq . '</script>' . "\\n";
    }}
}}, 5);
"""
    with open("first_rehab_wordpress.php", "w", encoding="utf-8") as f:
        f.write(php)

    json.loads(json.dumps(combined))
    print("OK:", len(combined["@graph"]), "graph nodes;",
          len(faq_schema()["mainEntity"]), "FAQ questions")
